package com.revivex.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="recovery_cases")
public class RecoveryCase { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(optional=false,cascade=CascadeType.ALL) private PaymentEvent payment; private String rootCause; private String recommendedAction; private double recoveryProbability; private BigDecimal expectedGrossRecovery; private BigDecimal expectedNetRecovery; private double confidence; private String stoppingRule; @Column(length=5000) private String reasoning; private String status; private int attempts; private BigDecimal actualRecovered; private Instant decidedAt; private String policyReason; private String stateVersion;
 public RecoveryCase(){} public RecoveryCase(PaymentEvent p,String cause,String action,double probability,BigDecimal gross,BigDecimal net,double confidence,String stop,String reasoning,String policyReason){payment=p;rootCause=cause;recommendedAction=action;recoveryProbability=probability;expectedGrossRecovery=gross;expectedNetRecovery=net;this.confidence=confidence;stoppingRule=stop;this.reasoning=reasoning;status="DETECTED";attempts=0;actualRecovered=BigDecimal.ZERO;decidedAt=Instant.now();this.policyReason=policyReason;stateVersion="1";}
 public Long getId(){return id;} public PaymentEvent getPayment(){return payment;} public String getRootCause(){return rootCause;} public String getRecommendedAction(){return recommendedAction;} public double getRecoveryProbability(){return recoveryProbability;} public BigDecimal getExpectedGrossRecovery(){return expectedGrossRecovery;} public BigDecimal getExpectedNetRecovery(){return expectedNetRecovery;} public double getConfidence(){return confidence;} public String getStoppingRule(){return stoppingRule;} public String getReasoning(){return reasoning;} public String getStatus(){return status;} public int getAttempts(){return attempts;} public BigDecimal getActualRecovered(){return actualRecovered;} public Instant getDecidedAt(){return decidedAt;} public String getPolicyReason(){return policyReason;} public String getStateVersion(){return stateVersion;}
 public void transition(String next){if("RECOVERED".equals(status)&&!"RECOVERED".equals(next))throw new IllegalStateException("INVALID_STATE_TRANSITION"); if("STOPPED".equals(status)&&!"STOPPED".equals(next)&&!"ESCALATED".equals(next))throw new IllegalStateException("INVALID_STATE_TRANSITION"); status=next;}
 public void analyzed(){transition("ANALYZED");} public void planned(){transition("PLANNED");} public void approve(){transition("POLICY_APPROVED");} public void pending(){transition("ACTION_PENDING");} public void executed(){transition("ACTION_EXECUTED");} public void awaiting(){transition("AWAITING_OUTCOME");} public void recovered(BigDecimal amount){if(amount==null)amount=BigDecimal.ZERO;actualRecovered=amount;payment.setRecovered(true);status="RECOVERED";attempts++;} public void stopped(){status="STOPPED";} public void blocked(){status="BLOCKED";} public void failed(){status="FAILED";} public void expired(){status="EXPIRED";} public void escalated(){status="ESCALATED";} public boolean isTerminal(){return java.util.Set.of("RECOVERED","STOPPED","BLOCKED","FAILED","EXPIRED","ESCALATED").contains(status);} }
